INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('およそ', 'およそ', 'N1', 'about; roughly; approximately', '① đại khái, khoảng （およそ1キロ、およその金額 đại khái khoảng tiền）＝約、だいたい② hoàn toàn...không( thể phủ định )　＝まったく③', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('極めて', 'きわめて', 'N1', 'exceedingly; extremely; decisively', 'cực kì, rất (極めて重要、極めて順調)　＝大変、非常に、とても', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('大層', 'たいそう', 'N1', 'very; extremely; exceedingly; greatly; terribly', 'rất nhiều (mức độ, quy mô)', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ごく', 'ごく', 'N1', 'quite; very', 'cực kì, rất (chỉ về lượng, lever cực kì thấp vd: ごくまれ cực kì hiếm, ごく少数)＝非常に、極めて', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('至って', 'いたって', 'N1', 'very much; exceedingly; extremely', 'rất(=大変、とても)', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('人一倍', 'ひといちばい', 'N1', '(much) more than others; exceedingly; extremely; unusually', 'rất nhiều, gấp đôi người bình thường(人一倍働く、人一倍の努力)', 'adv, adj-no, n') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('一通り', 'ひととおり', 'N1', 'generally; in the main; briefly (look over, explain, etc.); roughly; more or less', '① xem đại khái từ đầu đến cuối (一通り目を通す nhìn sơ qua)=ざっと、一応② đại khái từ đầu đến cuối (一通りできる đại khái có thể làm được)　＝だいたい、一応③ không phải...bình thường (dùng trong câu phủ định.)VD: あの人の日本文化に関する知識は、一通り（のもの）ではない', 'n, adj-no, adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('やや', 'やや', 'N1', 'a little; partially; somewhat; slightly; semi-; -ish; on the ... side; a short time; a while', 'một chút(やや背が高い)', 'adv, adj-f') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ややあって', 'ややあって', 'N1', 'a little while later; for a little while; some time later; for some time; presently', 'bỗng chốc (trạng thái gì đó đột ngột thay đổi)Trời đang trong xanh, bỗng chốc mây đen ùn ùn kéo đến.', 'exp') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ややもすれば', 'ややもすれば', 'N1', 'being apt to; being liable to; being inclined to', 'có cảm giác là tình trạng, trạng thái dễ xảy ra theo khuynh hướng như thế.ややもすれば、１時間も遅れる！', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('幾分', 'いくぶん', 'N1', 'somewhat; to some extent; to some degree', 'hơi hơi (痛みは幾分治まった chỗ bị đau đã hơi hơi đỡ rồi)', 'adv, n') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('そこそこ', 'そこそこ', 'N1', 'reasonably; fairly; all right; moderate', '① tàm tạm(そこそこできる、そこそこ注文が来る đơn đặt hàng cũng tàm tạm)② vội vàng(食事もそこそこに出かける ăn vội vàng rồi đi ra ngoài)③ khoảng độ, xấp xỉ (1000円そこそこで khoảng 1000yen)', 'adv, adj-no') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('Nもそこそこに', 'Nもそこそこに', 'N1', '', 'làm N vội vàng, qua loa', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('若干', 'じゃっかん', 'N1', 'some; few; a number of; a little (bit)', 'ít nhiều, một chút, một vài (若干遅れ気味だ cảm giác trễ một chút, 席にはまだ若干余裕がある)', 'adj-no') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('若干名', 'じゃっかんめい', 'N1', 'a few people; small number of people', 'chỉ có một vài người', 'n') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('いくらか', 'いくらか', 'N1', 'some; (a) little', 'một vài', 'adv, n, adj-no') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('今一つ', 'いまひとつ', 'N1', 'one more; another (one)', 'cảm giác thiếu thiếu gì đó khi đưa ra cảm nhận về vấn đề. VD: món ăn này vị thiếu thiếu chút gì đó.「味は どう?」「うーん，今一つだね」', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('今一', 'いまいち', 'N1', 'not quite (right); not very good; somewhat (lacking)', 'Tiếng lóng của 今一つ', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('散々', 'さんざん', 'N1', 'thoroughly; completely; utterly', 'mức độ cao của sự việc khiến mình kinh ngạc (さんざん遊び回った toàn rong chơi chỗ này chỗ kia)', 'adj-na, adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('散々な', '散々な', 'N1', '', 'Gay go; khốc liệt; dữ dội; buồn thảm', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ぐっと', 'ぐっと', 'N1', 'suddenly; at once; in one go; with a jerk; with a gulp', '① nhiều (ぐっと力に入れる dốc nhiều sức lực, ぐっと一息に飲む ひといき một hơi uống thật nhiều)② ③ hơn nhiều （ぐっと良くなった trở nên tốt hơn nhiều）', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('遥かに', 'はるかに', 'N1', 'by far; far and away; much; far', 'hơn nhiều, rất (はるかに面白い:thú vị hơn rất nhiều)', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('遥か昔', 'はるかむかし', 'N1', 'long ago', 'từ rất xa xưa', 'n') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('遥か遠く', 'はるかとおく', 'N1', 'far away in the distance; in the far distance', 'rất xa　（はるか遠くに: từ rất xa)', 'exp, adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('はるかかなた', 'はるかかなた', 'N1', 'faraway; far-off', 'xa xưa', 'adj-no, n') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('がっちり（と）する', 'がっちり（と）する', 'N1', '', '① chắc, chắc chắn (体ががっちりする: cơ thể rắn chắc)=がっしり② chắc, chặt (がっちり握手する: bắt tay chặt)＝しっかり③ chặt chẽ (お金にがっちりする chặt chẽ về tiền bạc)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('がっしり（と）する', 'がっしり（と）する', 'N1', '', 'rắn chắc, chắc chắn (がっしりした体、胸、ドア)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('くっきり（と）する', 'くっきり（と）する', 'N1', '', 'rõ ràng, đậm (màu sắc)(ぐっきり見える、ぐっきりと書く viết đậm)=はっきり', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('すんなり（と）する', 'すんなり（と）する', 'N1', '', '① mảnh khảnh (指、手足)=すらりと② trôi chảy (決まる、認める、自白する)＝あっさり', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ずんぐり', 'ずんぐり', 'N1', 'short and stout; small but wide around', 'nục nịch, phệ', 'adv, vs') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('着々（と）', '着々（と）', 'N1', '', 'tiến triển đều đều', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('着々と進む', '着々と進む', 'N1', '', 'tiến triển đều đều', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ぐんぐん（と）', 'ぐんぐん（と）', 'N1', '', '(động thực vật phát triển)nhanh chóng (伸びる、成長する)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ぐったりする', 'ぐったりする', 'N1', '', 'rã rời, rũ rượi (疲れてぐったりする：mệt mỏi rã rời, 植物がくったるする: thực vật héo rũ)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('げっそりする', 'げっそりする', 'N1', '', 'suy sụp, chán nản (病気でげっそりする、仕事が多すぎてげっそりする)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ひっそりする', 'ひっそりする', 'N1', '', 'tĩnh lặng, êm đềm (ひっそりした家、田舎でひっそりと暮らす)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ごたごた（と）する', 'ごたごた（と）する', 'N1', '', '① lung tung (ごたごたと置く để lung tung)② lung tung (ごたごた言う nói lung tung, không rõ ràng)③ lộn xộn, rối tung (tình trạng công ty đang rối tung)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ごちゃごちゃ（と）する', 'ごちゃごちゃ（と）する', 'N1', '', '① rối tung, lung tung (ごちゃごちゃと並ぶ, 頭の中にごちゃごちゃする)② lung tung (ごちゃごちゃ言う nói lung tung, không đi vào trọng tâm)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('べたべた（と）する', 'べたべた（と）する', 'N1', '', '① dính tèm lem (チョコレート、汗、油でべたべたする)② dán lung tung, dính lung tung (べたべたと貼る、べたべたとつく：)③ dính lấy nhau, ôm ấp (カップルはべたべたする)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('べたつく', 'べたつく', 'N1', 'to be sticky', 'dính lung tung', 'v5k, vi') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('さも', 'さも', 'N1', 'really (seem, appear, etc.); truly; evidently', 'rõ ràng, thực sự là (さも気持ちよさそうに：rõ ràng là tâm trạng có vẻ tốt, さも不満そうな顔)', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('如何にも', 'いかにも', 'N1', 'indeed; really; truly; just (like)', 'quả nhiên đúng là　( 如何: như thế nào, いかにも dù thế nào đi chăng nữa = quả nhiên đúng là )如何にも彼女は美人だ。', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('さぞ', 'さぞ', 'N1', 'surely; certainly; no doubt; must', 'chắc chắn là, đi kèm với だろう、でしょうさぞ大変だろう、さぞお疲れでしょう', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('さぞかし', 'さぞかし', 'N1', 'certainly; surely', 'chắc chắn là', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('さぞや', 'さぞや', 'N1', 'surely; certainly', 'chắc chắn là', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('何とぞ', 'なにとぞ', 'N1', 'please; kindly; I beg of you; if it pleases you', 'làm ơn、rất mong (何とぞお許しください、何とぞ宜しく)', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('何なりと', 'なんなりと', 'N1', 'anything; whatever; whatever one likes', 'bất cứ cái gì, chỗ nào (đưa ra lời đề nghị đối với đối phương)ご不明な点は、何なりとお尋ねください：hãy hỏi bất cứ điểm nào chưa rõ.', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('どんなことでも', 'どんなことでも', 'N1', '', 'bất cứ cái gì', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('どうやら', 'どうやら', 'N1', 'possibly; apparently; (seem) likely; seemingly', '① có vẻ như (どうやら間に合わせることができる có vẻ như sẽ kịp)② có vẻ như (どうやら雨になりそうだ)', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('よほど', 'よほど', 'N1', 'very; greatly; much; to a large extent; quite', 'rất nhiều, lắm, suy đoán lượng (よほど疲れていたのだろう、よほど機嫌が悪かったらしく)', 'adv, adj-no, adj-na') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('さほど', 'さほど', 'N1', '(not) so; (not) particularly; (not) very; (not) that much', 'không đến nỗi, không đến mức (さほど難しくない)', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('到底', 'とうてい', 'N1', '(cannot) possibly; (not) by any means; (not) at all; utterly; absolutely', 'hoàn toàn là...(câu phủ định hoặc ý nghĩa phủ định)　ngã chạm đến đáy → ý nghĩa hoàn toàn không tốt てうてい間に合わない、とうてい無理', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('一見', 'いっけん', 'N1', 'look; glimpse; glance', '① nhìn bề ngoài  (一見おとなしそうだが、気が強い)② nhìn bề ngoài (一見して偽物だと分かる)③ xem 1 lần (一見の価値がある đáng để đến xem 1 lần)', 'n, vs, vt, vi') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('一見して', '一見して', 'N1', '', 'nhìn sơ qua', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('百聞は一見に如かず', 'ひゃくぶんはいっけんにしかず', 'N1', 'seeing is believing; one eye-witness is better than many hearsays; a picture is worth a thousand words', 'trăm nghe không bằng một thấy', 'exp') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('一向に', 'いっこうに', 'N1', 'completely; absolutely; totally', 'hoàn toàn không muốn làm... (一向にやらない、動かない )', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('一概に', 'いちがいに', 'N1', 'unconditionally; as a rule', 'không thể khẳng định là, không thể kết luận là (phủ định hoặc ý nghĩa phủ định)一概には言えない không thể khẳng định là…', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ろくに。。。ない', 'ろくに。。。ない', 'N1', '', 'không làm tốt được, không hoàn thành tốt được (ろくに寝ていない　chẳng ngủ được chút nào、ろくに調査もしてくれない chẳng điều tra giúp chút nào)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ろくでもない', 'ろくでもない', 'N1', 'good-for-nothing; useless; worthless', 'tệ hại, chẳng làm được gì tốt　（ろくでもないやつ gã đàn ông chả có gì tốt）', 'exp, adj-i') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('何でも', 'なんでも', 'N1', 'any; anything; whatever; whatever one likes; everything; all', 'nghe nói là, theo tôi được biết là (何でも、Aさんは帰国したらしい)', 'exp') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('及び', 'および', 'N1', 'and; as well as', 'và', 'conj') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('並びに', 'ならびに', 'N1', 'and (also); both ... and; as well as', 'và (dùng trong nghi thức trang trọng)', 'conj') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('もしくは', 'もしくは', 'N1', 'or; otherwise', 'hoặc(=または)', 'conj') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('但し', 'ただし', 'N1', 'but; however; provided that', 'tuy nhiên　(đưa ra ngoại lệ so hoặc bổ sung cho điều kiện ở vế trước)VD:  rớt thi lại được nhưng tốn phí. Bệnh viện nghỉ chủ nhật nhưng cấp cứu vẫn tiếp nhận.', 'conj') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('なお', 'なお', 'N1', 'still; yet', '① thêm vào đó (những điều mục bổ sung cho sự việc phía trước)② vẫn vậy, không thay đổi (今なお bây giờ vẫn)③ hơn nữa, hơn thế nữa (なお悪いことに sự việc còn tồi tệ hơn,...)', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('なおさら', 'なおさら', 'N1', 'still more; even more; all the more', 'Hơn nữa', 'adv') ON CONFLICT DO NOTHING;
