INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('に弾みが付く', 'に弾みが付く', 'N1', '', 'có sự tiến triển mạnh mẽ', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('弾みで', '弾みで', 'N1', '', 'sự mạnh mẽ', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('~弾みに', '~弾みに', 'N1', '', 'một cách mạnh mẽ　（人とぶつかったはずみに財布を落とした。）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が粘る', 'が粘る', 'N1', '', '① dẻo, dính　(餅が粘る、)② làm đến cùng, dai như đĩa (nghĩa tốt và nghĩa không tốt)諦めずに粘る', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('粘り付く', 'ねばりつく', 'N1', 'to adhere to; to stick to; to cling to', 'dính chặt', 'v5k, vi') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('粘っこい', 'ねばっこい', 'N1', 'sticky; gummy; gooey; gluey; glutinous', 'dính dính, nhùng nhằng', 'adj-i') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('粘り強い', 'ねばりづよい', 'N1', 'tenacious; persevering; persistent; stubborn; steadfast', 'nhất quyết làm cho bằng được', 'adj-i') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('粘りがある⇔ない', '粘りがある⇔ない', 'N1', '', 'có ⇔ không có sự dính, sự nhùng nhằng', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が化ける', 'が化ける', 'N1', '', 'biến hóa, biến thành (キツネは人間の姿に、出資金が利益に)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が凋む', 'が凋む', 'N1', '', '① tàn, héo(花が)② xì, xẹp (風船が)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が萎びる', 'が萎びる', 'N1', '', '① Hoa quả héo ② Da nhăn nheo', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が萎れる', 'が萎れる', 'N1', '', 'hoa héo', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が弛む', 'が弛む', 'N1', '', 'chảy xệ, giãn xệ (ローブが、皮膚が、精神が xuống tinh thần)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('弛みがある⇔ない', '弛みがある⇔ない', 'N1', '', 'bị ⇔ không bị chảy xệ, giãn xệ', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を盛る', 'を盛る', 'N1', '', '① vun lên(茶碗にご飯を bới cơm vào bát, 皿に料理を、庭に土を)② bao gồm, có chứa', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を盛り付ける', 'を盛り付ける', 'N1', '', 'bày trí món ăn', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が盛り上がる', 'が盛り上がる', 'N1', '', 'phấn khích lên', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('盛り付け', 'もりつけ', 'N1', 'arrangement of food (on a dish); serving of (arranged) food', 'sự bày trí', 'n') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('大盛り', 'おおもり', 'N1', 'large serving; large portion', 'suất thức ăn nhiều', 'n') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を盛り込む', 'を盛り込む', 'N1', '', 'bao gồm', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を設ける', 'を設ける', 'N1', '', '① thiết đặt, lắp đặt, làm (相談窓口を、)② tạo ra (機会が設けられる、漢字の使用基準を)③ có con (子供をもうける)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を催す', 'を催す', 'N1', '', '① tổ chức (パーティーを)② cảm giác thấy (吐き気、眠気、尿意 にょうい muốn đi tiểu,...)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('催し物', 'もよおしもの', 'N1', '(program of) entertainments; special events; exhibitions; amusements; attractions', 'sự kiện', 'n') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を閉ざす', 'を閉ざす', 'N1', '', '① đóng lại (扉を、門を)② khép mình, không mở lòng, không mở lời (心を閉ざす、口を閉ざす)③ chắn, che (道を閉ざす、雲に閉ざされた空、氷に閉ざされた海)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を埋め立てる', 'を埋め立てる', 'N1', '', 'chôn lấp (海を埋め立てる)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('埋立地', 'うめたてち', 'N1', 'reclaimed land', 'khu vực được tạo ra từ việc lấp biển, ao hồ', 'n') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を要する', 'を要する', 'N1', '', 'đòi hỏi, yêu cầu (ダムの建設に要する費用、危険な作業に注意を要する）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を優先する', 'を優先する', 'N1', '', 'ưu tiên (家庭より仕事を優先する、すべてにする　ưu tiên hơn hết)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('優先的な', '優先的な', 'N1', '', 'mang tính ưu tiên', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('優先権', 'ゆうせんけん', 'N1', 'priority; preference; preferential right; right of way', 'quyền ưu tiên', 'n') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('優先順位', 'ゆうせんじゅんい', 'N1', 'priority; order of precedence', 'thứ tự được ưu tiên', 'n') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が遠ざかる', 'が遠ざかる', 'N1', '', '① trở nên rời xa dần (飛行機がだんだん遠ざかる、)② trở nên xa cách, hững hờ về mặt tình cảm (政界から遠ざかる)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が遠のく', 'が遠のく', 'N1', '', 'trở nên xa cách, hững hờ về mặt tình cảm, sở thích, tâm lý', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を遠ざける', 'を遠ざける', 'N1', '', '① lấy cái gì đó ra xa (マイクを遠ざける cách xa micro)② làm cho cái gì đó cách xa ra (息子から彼女を遠ざける làm cho cô gái rời xa cậu con trai)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を遠のける', 'を遠のける', 'N1', '', 'làm cho cái gì đó cách xa ra về mặt tâm lý, tình cảm', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('浸る', 'ひたる', 'N1', 'to be soaked in; to be flooded; to be submerged', '① để chìm vào, nhúng vào (温泉に浸る) =浸かる② đắm chìm trong (昔の思い出に、新婚気分、優越感、感度、余韻 よいん dư âm,　～雰囲気に)', 'v5r, vi') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('浸す', 'ひたす', 'N1', 'to soak; to dip; to steep; to immerse', '① nhúng vào (湯に体を、わかめを水に nhúng tảo vào nước)② thả hồn vào (感動に心を浸す)', 'v5s, vt') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が滅びる', 'が滅びる', 'N1', '', 'bị diệt vong (種、人類、民族、国、悪 あく, ...が滅びる)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が滅亡する', 'が滅亡する', 'N1', '', 'bị diệt vong', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を滅ぼす', 'を滅ぼす', 'N1', '', '① hủy diệt (人類を滅ぼす)② tàn phá cơ thể, tàn phá con người (ギャンブルで身を滅ぼす)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が栄える', 'が栄える', 'N1', '', 'phồn vinh (国、町、文化。。。が栄える)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が衰える', 'が衰える', 'N1', '', 'suy tàn', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が定まる', 'が定まる', 'N1', '', '① được quy định, được quyết định (今後の方針が定まる、人の運命は定まる vận mệnh đã được định đoạt)② an định, thường sử dụng cho trạng thái tự nhiên  (天候が定まる)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を定める', 'を定める', 'N1', '', 'quyết định, quy định thường được dùng trong tổ chức, cơ cấu nhà nước① quy định、ổn định  (今後の方針を定める、仕事を教師と定める ổn định công việc với nghề giáo viên)② quy định (法律を定める、人権は憲法に定められている nhân quyền được quyết định trong hiến pháp)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('(を)なす', '(を)なす', 'N1', '', 'tha động từ của なる① hình thành, tạo thành (群れ、列、層。。。)② không đạt được, thể phủ định (意味をなさない không có ý nghĩa, ～の用をなさない không dùng làm～)③ làm (今何をなすべく nên làm gì vào lúc này)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('災いを転じて福となす', 'わざわいをてんじてふくとなす', 'N1', 'to turn misfortune into fortune (esp. through one''s own efforts); to turn the potential disaster to one''s advantage', 'chuyển họa thành phúc', 'exp, v5s') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を担う', 'を担う', 'N1', '', 'thiên về gánh vác những điều mang tính trừu tượng như gánh vác đất nước, tương lai gia đình, trách nhiệm① gánh chịu (責任を、役割、任務、)② gánh vác (次代 thế hệ sau, 国民の期待、国の特集、国政、組織,) = 背負う、担ぐ③ mang vác trên vai (荷物を肩に、背中に) ＝担ぐ　chỉ có nghĩa là cầm, vác đồ vật', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('（が）とどまる', '（が）とどまる', 'N1', '', '① ở lại (現地に ở lại hiện trường, 現職に ở lại nơi làm việc, 故郷の島に ở lại quê hương biển đảo)② dừng lại ở (入場者は1000人に người vào xem thì dừng lại ở 1000 người)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('とどまるところを知らない', 'とどまるところをしらない', 'N1', 'knowing no bounds; showing no signs of stopping or slowing down', 'không biết sẽ dừng lại ở đâu', 'exp') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を思いとどまる', 'を思いとどまる', 'N1', '', 'bỏ suy nghĩ', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が踏みとどまる', 'が踏みとどまる', 'N1', '', 'dừng lại', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('をとどめる', 'をとどめる', 'N1', '', '(を)　lưu giữ, để cái gì đó bao gồm sự vật, sự việc, tâm trạng (に) ở đâu đó, ở mức độ nào đó, địa điểm vô hình hay hữu hình① để lại, giữ lại (お客を車内に để hành khách ở trong xe)② dừng lại (足をとどめる dừng chân)③ kiềm nén lại, giữ lại ở mức (被害を最小限に giữ thiệt hại ở mức tối thiểu, 厳重注意を dừng lại ở mức chú ý nghiêm khắc)④ để cái gì đó lại (歴史に名を để lại tên trong lịch sử, 記録、記憶、心に để lại trong kí ức, trong tim)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を押しとどめる', 'を押しとどめる', 'N1', '', 'dừng lại', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を引きとどめる', 'を引きとどめる', 'N1', '', 'kéo lại', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が尽きる', 'が尽きる', 'N1', '', '① cạn kiệt (お金、化石エネルギー、策、)② kết thúc, hoàn tất (悩みが尽きる)③', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が枯渇する', 'が枯渇する', 'N1', '', 'cạn kiệt, khô cạn (井戸が枯渇する)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が消滅する', 'が消滅する', 'N1', '', 'bị tiêu diệt, biến mất', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を尽くす', 'を尽くす', 'N1', '', '①　dốc hết sức lực (手を尽くす thử hết mọi cách、贅沢の限りに尽くした豪邸 ごうてい biệt thự mà đã dốc hết tất cả sự xa hoa)② phục vụ, cống hiến (社会に尽くす、夫のために尽くす)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が奉仕する', 'が奉仕する', 'N1', '', 'phục vụ, cống hiến', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('「動詞」+尽くす', '「動詞」+尽くす', 'N1', '', 'làm hết (食料を食べつくす ăn hết, 呆然で立ち尽くす ほうぜん đứng thẫn thờ ra vì ngạc nhiên, 焼き尽くす cháy rụi toàn bộ)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が臨む', 'が臨む', 'N1', '', '① hướng về phía (ホテルは海に臨む)② sẵn sàng hướng đến mục tiêu (試験、試合、式、面接、本番…　に臨む)③ hướng đến, đương đầu với (苦難、別れ、危険 。。。に臨む)④ đối ứng, đối xử (学生に公平な態度で臨む、厳しい方針で臨む đối ứng bằng cách nghiêm khắc nhất)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を損なる', 'を損なる', 'N1', '', 'gây thiệt hại, gây hại (健康、美観 mĩ quan, 景観、機嫌、命、器物　きぶつ 、。。。)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を損ねる', 'を損ねる', 'N1', '', 'làm tổn hại', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が漂う', 'が漂う', 'N1', '', '① bay bồng bềnh (雲が空を、香りが)② bộc lộ ra, bao trùm (険悪な空気、雰囲気、～ムード bầu không khí, 哀愁　あいしゅう sầu thảm, 妖気 ようき yêu khí)③ phiêu bạt (他国に漂う trôi dạt đến nước khác)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('（が）さまよう', '（が）さまよう', 'N1', '', 'phiêu bạt', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が満ちる', 'が満ちる', 'N1', '', '① tràn đầy (水が、自信に、期待に、体に活力が、活気に、)② đầy, đủ đầy, không bị khuyết (潮が満ちる thủy triều dâng lên, 月が満ちる trăng tròn)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が満ち溢れる', 'が満ち溢れる', 'N1', '', 'tràn đầy', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('満潮', 'まんちょう', 'N1', 'high tide; high water; full tide', 'thủy triều lên', 'n') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('満月', 'まんげつ', 'N1', 'full moon', 'trăng tròn', 'n, adj-no') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('満たない', 'みたない', 'N1', 'less than; fraction of; below', 'chưa đạt đến, chưa đủ, chưa hội đủ (３カ月に chưa đến 3 tháng, 合格点に chưa đủ điểm đậu, １０万に  chưa đến 10 man, 条件、基準に)', 'exp') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を満たす', 'を満たす', 'N1', '', '① làm đầy (バケツに水を、空腹を満たす、幸福感を、結婚生活に何か満たされない )② hội đủ, đạt đủ (条件を満たす đạt đủ điều kiện)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('をまかなう', 'をまかなう', 'N1', '', '① trang trải (学費を、家計を、経費を、)② cung cấp (学生に食事をまかなってくれる  cung cấp thức ăn cho học sinh)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('をやり繰りする', 'をやり繰りする', 'N1', '', 'trang trải', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が匹敵する', 'が匹敵する', 'N1', '', 'sánh vai, tương đương với, vế trước là từ chỉ mức độ cao 彼はまだ子供だが、大人の選手に匹敵する能力の持ち主だ。この地震の被害の規模は、関東大震災の被害に匹敵する。', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('（が）はびこる', '（が）はびこる', 'N1', '', 'hoành hành (庭に雑草が　ざっそう、役人に汚職が　tham nhũng hoành hoành trong công chức, 悪が、)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が陥る', 'が陥る', 'N1', '', '① rơi vào (経営不振、錯覚、スランプ khủng hoảng, パニック hoảng loạn, ジレンマ　tiến thoái lưỡng nan)② rơi vào chỗ trũng  (川の深み　rơi vào chỗ sâu của con sông)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が勝る', 'が勝る', 'N1', '', 'vượt trội, áp đảo (相手チームより/に　áp đảo đối thủ、)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('勝るとも劣らない', 'まさるともおとらない', 'N1', 'not at all inferior to; rival or surpass; compare favorably (with)', 'cho dù có hơn như thế nữa cũng không chịu thua', 'exp, adj-i') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を帯びる', 'を帯びる', 'N1', '', '① có hơi hướng, có vẻ (青みを帯びた白 màu trắng có hơi xanh, 丸みを帯びた形 hình dạng hơi tròn, 酒気帯び運転　しゅき  lái xe mà có hơi rượu)② nhận trách nhiệm, nhiệm vụ (首相の特命を nhận sứ mệnh đặc biệt của thủ tướng)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が鈍る', 'が鈍る', 'N1', '', '① trở nên cùn, không còn sắc sảo nữa (腕が鈍った tay nghề kém đi, 決心 quyết tâm giảm sút)② cùn, không còn sắc, bén (刃物が鈍る)③ không còn tốt nữa (伸びが鈍る sự tăng trưởng trở nên kém)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('（が）ありふれている', '（が）ありふれている', 'N1', '', 'có đụng chạm rồi ⇒ trở nên bình thường, không còn đặc biệt nữa　（nguyên mẫu là ありふれる nhưng ít dùng）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ありふれた+名詞', 'ありふれた+名詞', 'N1', '', 'trở nên tầm thường, không còn đặc biệt, hấp dẫn nữa (ありふれたもの những thứ tầm thường, )', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('（が）冴える', '（が）冴える', 'N1', '', '① trong trẻo, trong vắt (月の光、笛の音)② minh mẫn, đưa ra những ý kiến, hành động sáng suốt (職人の技がさえる)③ vẻ ngoài, khí sắc không tốt (dùng phủ định)(見かけはさえない、顔がさえない、表情がさえない)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('さえ渡る', 'さえわたる', 'N1', 'to be clear; to be distinct; to be precise', 'trong trẻo, minh mẫn, sáng suốt', 'v5r, vi') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('勘がさえる', '勘がさえる', 'N1', '', 'cảm giác nhạy bén', '') ON CONFLICT DO NOTHING;
