INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('紛らわしい', 'まぎらわしい', 'N1', 'easily mixed up (e.g. similar words); easily mistaken; confusing; misleading; equivocal; ambiguous', 'bị hiểu lầm, bị nhầm (書く”れ”の字は”わ”と紛らわしい)', 'adj-i') ON CONFLICT DO NOTHING;
