INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('まちまちな', 'まちまちな', 'N1', '', 'linh tinh, nhiều loại khác nhau, không thống nhất (まちまちな服装 trang phục lung tung) =さまざま、いろいろな', '') ON CONFLICT DO NOTHING;
