INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('露骨な', '露骨な', 'N1', '', 'rõ ràng, không giấu diếm (露骨な敵意、描写、表現)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('あからさま', 'あからさま', 'N1', 'plain; frank; candid; open; direct; straightforward; unabashed; blatant; flagrant', 'minh bạch, rõ ràng', 'adj-na, adj-no') ON CONFLICT DO NOTHING;
