INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が懐く', 'が懐く', 'N1', '', 'trở nên thân thiết, gắn bó (先生に子供たちは懐いた、犬が私に懐かない )', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('人懐っこい', 'ひとなつっこい', 'N1', 'friendly; affable; amiable; sociable; loving company; (animals) taking kindly to people', 'dễ thân thiết với mọi người', 'adj-i') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を構う', 'を構う', 'N1', '', 'chăm sóc, quan tâm (子供を構う)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を見せびらかす', 'を見せびらかす', 'N1', '', 'khoe (ゲーム機を友達に見せびらかす）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('をねだる', 'をねだる', 'N1', '', 'năn nỉ, xin xỏ (小遣い、お土産をねだる）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('おねだり', 'おねだり', 'N1', 'begging; pestering; pleading; coaxing', 'cầu xin (お母さんにおねだりをする)', 'n') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を宥める', 'を宥める', 'N1', '', 'dỗ dành, xoa dịu (泣いている妹をなだめる、父の怒りをなだめる）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('をいたわる', 'をいたわる', 'N1', '', 'chăm sóc tử tế (老人、病人をいたわる、体をいたわる）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('いたわり', 'いたわり', 'N1', 'sympathy; consideration; carefulness; attention', 'cấn thận (いたわりの言葉 từ ngữ được trau chuốt, đúng dắn )', 'n, adj-no') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が触れ合う', 'が触れ合う', 'N1', '', '① chạm (手と手が触れ合う）② tiếp xúc (動物と触れ合う）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('触れ合い', 'ふれあい', 'N1', 'contact; connectedness; rapport; mutual touching', 'sự kết nối, tiếp xúc (親子の触れ合い sự kết nối giữ bố mẹ và con cái, 心の触れ合い kết nối trái tim )', 'n, adj-f') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('（が）とぼける', '（が）とぼける', 'N1', '', '① giả vờ không biết ② ngây ngô (とぼけた表情、口調)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('をごまかす', 'をごまかす', 'N1', '', '① nói dối, lừa dối, lơ đi (つり銭をごまかす lờ đi tiền thừa, không thối lại )② né tránh, che đậy, đánh trống lảng (失敗をごまかす、その場をごまかす、自分の気持ちを)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を脅かす', 'を脅かす', 'N1', '', 'đe dọa, hù dọa (ひどい不況が庶民の生活を脅かす)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('（が）おびえる', '（が）おびえる', 'N1', '', 'sợ hãi, trở thành nỗi sợ hãi (大きな音におびえる　sợ âm thanh lớn, 余震、戦争、悪夢 あくむ をおびえる)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が戸惑う', 'が戸惑う', 'N1', '', 'hoang mang, lúng túng (突然指名されて戸惑った)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('戸惑いが覚える', '戸惑いが覚える', 'N1', '', 'bị hoang mang, lúng túng', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を慎む', 'を慎む', 'N1', '', '① cẩn thận, thận trọng (言葉を慎む, 言動を慎む)② thận trọng, cân nhắc, tránh ( 辛いものを慎む thận trọng với đồ ăn cay )', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('慎み深い', 'つつしみぶかい', 'N1', 'discreet; modest; cautious', 'cẩn trọng', 'adj-i') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('慎みがある⇔ない', '慎みがある⇔ない', 'N1', '', 'có ⇔ không có sự cẩn trọng', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('をわきまえる', 'をわきまえる', 'N1', '', 'nhận ra, hiểu (立場をわきまえる、善悪　ぜんあく　thiện ác, 公私の別 sự khác nhau giữa công và tư, 場を', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を心得る', 'を心得る', 'N1', '', 'nhận ra, thấu hiểu', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を惜しむ', 'を惜しむ', 'N1', '', '① hối tiếc, miễn cưỡng thực hiện điều gì (別れを惜しむ、早すぎる死を惜しむ, 友達となごりを dư âm )② tiếc nuối, dùng kiểu " không uổng, không tiếc" (努力を惜しんではならない không uổng công đã nổ lực )', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('寸暇を惜しんで+「動詞」', '寸暇を惜しんで+「動詞」', 'N1', '', 'tiếc thời gian rảnh rỗi nên làm gì đó', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('骨身を惜しまず働く', '骨身を惜しまず働く', 'N1', '', 'làm việc quên mình', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('をはばかる', 'をはばかる', 'N1', '', 'lo lắng người khác biết (外聞をはばかる話 chuyện mà mình lo lắng cho danh dự của bản thân )', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が手こずる', 'が手こずる', 'N1', '', 'khó khăn, vất vả (わがままな子供に手こずらされる bị khó khăn vất vả với lũ trẻ quậy phá )', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が手を焼く', 'が手を焼く', 'N1', '', 'bó tay, khó làm được', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が懲りる', 'が懲りる', 'N1', '', 'rút ra bài học kinh nghiệm cho bản thân (失敗に懲りる rút ra kinh nghiệm từ thất bại )', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('懲り懲り', 'こりごり', 'N1', 'having had enough (of); fed up (with); sick and tired (of)', 'tỉnh ngộ, rút kinh nghiệm (登山はもうこりごりだ）', 'adj-na') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('をとがめる', 'をとがめる', 'N1', '', '① cảm giác cắn rứt （良心がとがめる、気がとがめる）② khiển trách, truy cứu trách nhiệm (上司にとがめられた bị cấp trên khiển trách, 警官にとがめられる )', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を非難する', 'を非難する', 'N1', '', 'chỉ trích, khiển trách', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を償う', 'を償う', 'N1', '', '① bồi thường (損害を償う）② chuộc lỗi (どんな方法で罪を償えるのだろうか làm cách nào để có thể chuộc lại lỗi lầm của mình )', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('償いをする', '償いをする', 'N1', '', 'bồi thường', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が凝る', 'が凝る', 'N1', '', '① miệt mài, say mê (お菓子作りに凝る）② đặc biệt, riêng biệt, độc lạ (凝った料理、凝ったデザイン、凝った装飾　そうしょく)③ cứng đờ, ê ẩm (肩が凝る)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が凝り固まる', 'が凝り固まる', 'N1', '', 'cứng lại', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を凝らす', 'を凝らす', 'N1', '', '① tập trung ánh mắt, hơi thở để làm gì đó ( 目を凝らす、息を凝らす)② cất công, công phu vào điều gì (　デザインに工夫を凝らす、)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が。。。にこだわる', 'が。。。にこだわる', 'N1', '', '① cứ mãi để tâm, tiêu cực (失敗, 小さいこと、つまらないこと、体面　thể diện, メンツ　sỉ diện にこだわる)② để ý kĩ, tích cực (材料の質に chú ý, để ý đến chất lượng nguyên liệu)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('こだわりがある⇔ない', 'こだわりがある⇔ない', 'N1', '', 'có ⇔ không để tâm, bận tâm, sự câu nệ', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が徹する', 'が徹する', 'N1', '', '① tập trung vào, chuyên tâm vào　= 打ち込む、専念する② xuyên suốt (夜を徹して話し合う) =貫く', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を極める', 'を極める', 'N1', '', '① chinh phục được những thứ cực hạn, cực độ  (南極点、頂点、山頂。。。を極める）② làm cho cái gì đó trở nên cực hạn (困難、繁栄、栄華 えいが、口を極める mồm mép quá đáng )', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を究める', 'を究める', 'N1', '', 'đạt đến đỉnh cao đối với vấn đề gì đó ( 真理、芸の道 )', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('窮める', 'きわめる', 'N1', 'to carry to extremes; to go to the end of something; to reach the limits of something', 'đạt đến đỉnh cao đối với vấn đề gì đó ( 真理、芸の道 )', 'v1, vt') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が極まる', 'が極まる', 'N1', '', 'rơi vào sự cùng cực của vấn đề không tốt (失礼窮まる態度、進退窮まる　đường cùng tiến thoái lưỡng nan)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('窮まる', 'きわまる', 'N1', 'to reach an extreme; to reach a limit; to terminate; to come to an end', 'rơi vào sự cùng cực của vấn đề không tốt (失礼窮まる態度、進退窮まる　đường cùng tiến thoái lưỡng nan)', 'v5r, vi') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を遂げる', 'を遂げる', 'N1', '', 'đạt được、chạm đến ngưỡng  (目的、思い, 望み、志、発達、急成長、初優勝、悲惨な最期を遂げる)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を掲げる', 'を掲げる', 'N1', '', '① treo lên (看板、国旗を掲げる）② nêu lên (理想を）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('国旗を掲揚する', '国旗を掲揚する', 'N1', '', 'giương cờ', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('便宜を図る', 'べんぎをはかる', 'N1', 'to suit the convenience of; to accommodate', 'chu cấp tiện nghi', 'exp, v5r') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('再起を図る', '再起を図る', 'N1', '', 'lên kế hoạch quay lại sân khấu, tái xuất', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を操る', 'を操る', 'N1', '', '① điều khiển, chi phối (人の心、人形を操る、運命に操られる)② thông thạo, sử dụng khéo léo (５か国語を、道具）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('操り人形', 'あやつりにんぎょう', 'N1', 'puppet; marionette', 'con rối', 'n') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を仕切る', 'を仕切る', 'N1', '', '① chia ra, phân chia khu vực (部屋を仕切る）② kiểm soát, quản lý mọi thứ trong phạm vi được giao (一人で宴会を仕切る えんかい buổi tiệc )', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('取り仕切る', 'とりしきる', 'N1', 'to manage (all by oneself); to control; to run; to take charge of', 'kiểm soát, quản lý mọi thứ trong phạm vi được giao', 'v5r, vt') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を施す', 'を施す', 'N1', '', '① tiến hành (治療を、対策を)② thêm vào, bổ sung (写真に修正を、装飾が施される）③ làm cho, cho (植物に水/肥料を施す ひりょう bón phân, tưới nước cho cây、貧しい人々にお金を施す）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('手の施しようがない', 'てのほどこしようがない', 'N1', 'beyond help; there''s nothing that can be done', 'bó tay, không xử lý được', 'exp, adj-i') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が間に合う', 'が間に合う', 'N1', '', '① vừa đủ so với nhu cầu đối với trường hợp cụ thể (何とか間に合う  vừa đủ )② ーている dùng để nói về doanh số bán hàng (間に合っている doanh số cũng ổn )', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を間に合わせる', 'を間に合わせる', 'N1', '', 'xoay sở, cân đối cho đủ trong trường hợp cụ thể  (花瓶がないのでワインの瓶で間に合わせる)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('をこなす', 'をこなす', 'N1', '', '① hoàn thành tốt từ đầu đến cuối (あの俳優はどんな役でもうまくこなす）② hoàn thành mục tiêu ( 仕事量、ノルマ chỉ tiêu sản xuất, 多量の注文を）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を使いこなす', 'を使いこなす', 'N1', '', 'sử dụng thành thạo', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を乗りこなす', 'を乗りこなす', 'N1', '', 'cưỡi thành thạo ( ngựa)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を弾きこなす', 'を弾きこなす', 'N1', '', 'đánh đàn thành thạo', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を着こなす', 'を着こなす', 'N1', '', 'mặc đồ hợp mốt', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('数をこなす', 'かずをこなす', 'N1', 'to deal with a large number', 'hoàn thành đủ số lượng', 'exp, v5s') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('(が)はかどる', '(が)はかどる', 'N1', '', 'tiến triển thuận lợi, tiến bộ (勉強、工事がはかどる)　＝順調する', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が行き詰まる', 'が行き詰まる', 'N1', '', 'bị mắc kẹt không tiến triển tiếp được (研究に行き詰まる、交渉が行き詰まる、経営が行き詰まる）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('行き詰まりを感じる', '行き詰まりを感じる', 'N1', '', 'cảm thấy bị mắc kẹt không tiến triển được', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を据え置く', 'を据え置く', 'N1', '', '① dựng thẳng đứng (銅像を据え置く、据え置き型のエアコン )② giữ nguyên, duy trì như vậy (賃金が据え置かれる tiền công được giữ nguyên) =を維持する、を保つ', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が携わる', 'が携わる', 'N1', '', 'tham gia vào viêc gì đó, làm việc có liên quan đến ( 製薬に　bào chế thuốc、開発に khai thác phát triển)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を営む', 'を営む', 'N1', '', '① kinh doanh② tiến hành, chỉ đạo sự kiện③ làm việc', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を携える', 'を携える', 'N1', '', '① cầm theo cái gì đó khi đi đâu đó (武器を身に携える cầm theo vũ khí trong người)② dắt theo (家族を携えて赴任した）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を募る', 'を募る', 'N1', '', 'chiêu mộ, thu thập （募金を、会員を）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が募る', 'が募る', 'N1', '', 'mãnh liệt về cảm xúc, cảm giác (望郷の念が　ぼうきょう nỗi nhớ quê hương trở trở nên da diết, dữ dội、寒さが）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が押し寄せる', 'が押し寄せる', 'N1', '', 'dâng trào lên vây lấy …(高波が、敵の大群が城に）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('（が）たどる', '（が）たどる', 'N1', '', '① lần theo con đường (小道を、家路を いえじ đường về nhà )② lần mò theo đầu mối ( 記憶をたどる、話の筋を）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('悪化', 'あっか', 'N1', 'deterioration; getting worse; worsening; aggravation; degeneration; corruption', 'tiến lên theo con đường ngày càng xấu/ sự sụp đổ, diệt vong', 'n, vs, vi') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('破滅の一途をたどる', '破滅の一途をたどる', 'N1', '', 'tiến lên theo con đường ngày càng xấu/ sự sụp đổ, diệt vong', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('平行線をたどる', '平行線をたどる', 'N1', '', 'đi theo đường song song, không bao giờ gặp nhau', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('奇跡をたどる', '奇跡をたどる', 'N1', '', 'tiến lên theo kì tích, phép màu', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を探る', 'を探る', 'N1', '', '① lục lọi、sờ soạng để tìm kiếm (ポケットを、手で探る sờ soạng, dò dẫm lung tung )② nhận ra, tìm ra ( 敵の動きを、部長の真意を）③ tìm kiếm (新しい道、原因、解決、可能性を）④ thám hiểm ( 洞窟を探る どうくつ thám hiểm hang động ) = を探検する たんけん', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を探り当てる', 'を探り当てる', 'N1', '', 'dò dẫm phát hiện ra', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を裏付ける', 'を裏付ける', 'N1', '', 'xác thực, chứng minh ( 彼の犯行を裏付ける証拠はない)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('裏付け捜査', 'うらづけそうさ', 'N1', 'search for corroborative evidence', 'điểu tra, tìm kiếm dấu hiệu, bằng chứng', 'n') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を立証する', 'を立証する', 'N1', '', 'đưa ra chứng cớ để chứng minh', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('をうかがう', 'をうかがう', 'N1', '', '① để ý thăm dò (不審な男が家の中の様子を）② nhắm đến mục tiêu （機会、チャンス、相手のすき。。。 をうかがう）③ thấu hiểu (決心の固さ quyết tâm cứng rắn、決意のほど mức độ của sự quyết ý。。。がうかがう）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('顔色をうかがう', '顔色をうかがう', 'N1', '', 'thăm dò, để ý sắc mặt', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('辺りをうかがう', '辺りをうかがう', 'N1', '', 'thăm dò hàng xóm xung quanh', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を謀る', 'を謀る', 'N1', '', 'âm mưu, đặt mưa tính kế ( 暗殺を、個人情報の流出を謀る âm mưa đưa thông tinh cá nhân ra ngoài)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を企む', 'を企む', 'N1', '', 'âm mưu, mưa đồ xấu', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を企てる', 'を企てる', 'N1', '', 'âm mưu', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を欺く', 'を欺く', 'N1', '', 'lừa đảo (人を、敵を）＝だます', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を阻む', 'を阻む', 'N1', '', 'cản trở (行く手を、景気の回復を）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を遮る', 'を遮る', 'N1', '', '① ngăn chặn (ブラインドで直射日光を遮る chặn ánh sáng mặt trời bằng rèm cửa, 霧が視界を遮る)② chặn đứng (人の話、発言、　木が道、行く手を遮る)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が障る', 'が障る', 'N1', '', '① gây hại、gây ảnh hưởng (体に障る、仕事に障る)② gây khó chịu (神経に障る)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('障りがある', '障りがある', 'N1', '', 'có hại', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を蝕む', 'を蝕む', 'N1', '', 'đục khoét, làm hao mòn, suy kiệt (病が体を蝕む、森は酸性雨に蝕まれる rừng bị mưa axit làm suy kiệt )', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('(が)こもる', '(が)こもる', 'N1', '', '① nhốt mình trong phòng (家にこもる、僧が寺/山にこもる 　そう  nhà sư nhốt mình trong núi/ chùa.② bí hơi, hơi được giữ trong phòng (湿気　しっけ、匂い、煙、熱気。。。がこもる）③ tiếng bị giữ lại bên trong, không thể nói ra ngoài (耳に水が入ると、自分の声がこもって聞こえる）④ giữ trong lòng ( 練習に熱がこもる giữ nhiệt huyết、心のこもったプレゼント món quà giữ trong tim)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が閉じこもる', 'が閉じこもる', 'N1', '', 'giam mình trong phòng', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('潜む', 'ひそむ', 'N1', 'to lurk; to be hidden; to be concealed; to lie dormant; to be latent', 'ẩn nấp, ẩn náu (犯人は知人のアパートに潜む , トラは草むらに潜む, 頭痛に悪い病気が潜む ủ bệnh)', 'v5m, vi') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が隠れる', 'が隠れる', 'N1', '', 'ẩn nấp, ẩn náu', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が潜伏する', 'が潜伏する', 'N1', '', 'ẩn nấp, ủ bệnh', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を潜める', 'を潜める', 'N1', '', '① giấu diếm (身を潜める、影を潜める)② che giấu (声を潜める nói nhỏ để người khác không nghe, 息を潜める、鳴りを潜める　che giấu sự nỗi tiếng, sống cuộc sống thanh bình)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が揺らぐ', 'が揺らぐ', 'N1', '', '① rung lắc, không vững (土台が揺らぐ、政権が揺らぐ chính quyền bị lay chuyển)② đung đưa (柳の枝が風に揺らいでいる）③ rung động trong lòng (心、気持ち、自信、決心。。。が揺らぐ)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を揺るがす', 'を揺るがす', 'N1', '', 'làm rung chuyển （社会を揺るがす事件）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('（が）もめる', '（が）もめる', 'N1', '', '① tranh cãi, tranh luận (雇用側と労働側がもめる、A国とB国がもめる）② lo lắng （気にもめる)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('もめ事', 'もめごと', 'N1', 'quarrel; fight; trouble; dispute; friction; discord', 'tranh cãi', 'n') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('大もめ', '大もめ', 'N1', '', 'tranh cãi gay gắt', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が翻る', 'が翻る', 'N1', '', '① bay phất phới (旗が風に翻っている）② bị thay đổi nhanh chóng (考え、意見、決意、態度 が翻る）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を翻す', 'を翻す', 'N1', '', '① lật lại (手のひらを翻す）② làm cho tung bay phất phới (スカーフを風に翻す）③ thay đổi nhanh chóng (考え、意見、決意、態度。。。を翻す）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が覆る', 'が覆る', 'N1', '', '① bị lật lại, bị bác bỏ (定説、判定、前提、評価。。。）② bị lật ngược (3点差が覆る bị lật ngược 3 điểm cách biệt, 上下が覆る )③ bị lật (ボートが覆る thuyền bị lật)④ bị lật đổ （国家体制が覆る）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が転覆する', 'が転覆する', 'N1', '', 'bị lật đổ, lật úp ( ボート、国家体制)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('（が）ひっくり返る', '（が）ひっくり返る', 'N1', '', 'bị lật ngược lại', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を覆す', 'を覆す', 'N1', '', '① làm ngược lại với dự đoán, phán quyết (予想、判定、評価、予測、定説、常識、理論、。。。）② lật ngược tình thế ( ５点差を覆す）③ làm lật úp （大波がボートを覆す）④ lật đổ chính quyền ( 政権、天下を　てんか thiên hạ, quyền cai trị ）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('をひっくり返す', 'をひっくり返す', 'N1', '', 'lật đổ', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('（が）ゆがむ', '（が）ゆがむ', 'N1', '', '① bị méo mó (メガネの枠、目の前が hình ảnh trước mắt bị méo mó)② tính cách lệch lạc (心がゆがむ）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ゆがみがある⇔ない', 'ゆがみがある⇔ない', 'N1', '', 'có ⇔ không có sự méo mó, lệch lạc', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ゆがみが生じる', 'ゆがみが生じる', 'N1', '', 'phát sinh sự méo mó, lệch lạc', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('（が）こじれる', '（が）こじれる', 'N1', '', '① làm tình hình trở nên phức tạp (話、仲、交渉、問題。。。がこじれる）② bệnh trở nên trầm trọng ( 風邪をこじらせる）　dùng thể sai khiến và trợ từ を', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が食い違う', 'が食い違う', 'N1', '', 'không thống nhất, không ăn nhập gì hết (意見が食い違う）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が隔たる', 'が隔たる', 'N1', '', 'xa cách (故郷から隔たった場所、考えが隔たる）　= 離れる', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('時間が隔たる', '時間が隔たる', 'N1', '', 'thời gian xa cách, tháng năm xa cách', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('隔たりがある⇔ない', '隔たりがある⇔ない', 'N1', '', 'có ⇔ không có xa cách', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('隔たりができる', '隔たりができる', 'N1', '', 'bắt đầu có sự xa cách (夫婦の間に隔たりができた đã xuất hiện sự xa cách giữa 2 vợ chồng)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を隔てる', 'を隔てる', 'N1', '', 'chia ra, ngăn ra (テーブルを隔てる、２０年の時を隔てる xa cách 20 năm trời, 二人の仲を隔てる)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('隔てがある⇔ない', '隔てがある⇔ない', 'N1', '', 'có ⇔ không có sự ngăn cách ( 隔てのない間柄 あいだがら mối quan hệ không bị ngăn cách)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('隔てなく', '隔てなく', 'N1', '', 'không có xử phân biệt ( 兄弟を隔てなく扱う đối xử không có sự phân biệt anh em)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が釣り合う', 'が釣り合う', 'N1', '', '① cân bằng (収入と支出が釣り合う）② xứng lứa vừa đôi ( 人は自分と釣り合う人を好きになる、大女優に釣り合う男性)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('釣り合いが取れる', '釣り合いが取れる', 'N1', '', 'có sự tương xứng, cân bằng ・làm cho cân bằng, tương xứng', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を取る', 'を取る', 'N1', '', 'có sự tương xứng, cân bằng ・làm cho cân bằng, tương xứng', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が絡む', 'が絡む', 'N1', '', '① xung đột (利害が絡む、この事件には政治家が絡む）② cãi cọ, gây sự (酔うと人に絡む）③ leo, quấn (フェンスに朝顔のつるが絡んでいる dây bìm bìm quấn quanh hàng rào)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('「名詞」+絡み', '「名詞」+絡み', 'N1', '', 'có dính líu, liên quan đến N (政治家絡みの事件 vụ việc có liên quan đến nhà chính trị）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が絡まる', 'が絡まる', 'N1', '', 'quấn quanh, vướng quanh ( 木の幹にツタが絡まる、毛糸が絡まっている dây bị rối, 足が絡まる）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を絡める', 'を絡める', 'N1', '', '① hòa trộn (焼いた肉のたれを絡める、)② có liên hệ với nhau (高齢者の問題は、少子化問題と絡めて考える）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を関係づける', 'を関係づける', 'N1', '', 'có liên hệ với nhau', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が紛れる', 'が紛れる', 'N1', '', '① bị lẫn vào (周りの音に紛れて相手の声が聞こえない、人込みに紛れて彼女、闇に、忙しさに）② bị sao nhãng sang hướng khác (笑顔で悲しみが紛れた、冷やすと痛みが紛れる )', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が紛れ込む', 'が紛れ込む', 'N1', '', 'hòa vào, thâm nhập vào (社員の中にスパイが紛れ込む）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('~紛れ', '~紛れ', 'N1', '', 'Sự may mắn, cơ may, ăn hên', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('闇に紛れる', '闇に紛れる', 'N1', '', 'lẩn vào trong màn đêm', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('どさくさに紛れる', 'どさくさに紛れる', 'N1', '', 'lẩn vào trong sự lộn xộn (放火犯は火事のどさくさに紛れて逃げた）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('気を紛らす', 'きをまぎらす', 'N1', 'to distract oneself; to take one''s mind off one''s worries', 'làm cho phân tâm', 'exp, v5s') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('（が）かさばる', '（が）かさばる', 'N1', '', 'cồng kềnh （荷物がかさばる）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('嵩', 'かさ', 'N1', 'bulk; volume; quantity', 'khối lượng lớn (かさが張る　lượng lớn được tăng lên、雨で川の水嵩が増す）', 'n') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('（が）かさむ', '（が）かさむ', 'N1', '', 'tăng lên (コスト、費用、経費、がかさむ）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('（が）しなびる', '（が）しなびる', 'N1', '', '① hoa quả héo (花、果物がしなびる）② da nhăn nheo (手の皮膚がしなびた da tay đã nhăn nheo )', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('がしおれる', 'がしおれる', 'N1', '', 'khô héo ( vẫn có khả năng hồi phục)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('がしなびる', 'がしなびる', 'N1', '', 'khô héo ( vẫn có khả năng hồi phục)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が枯れる', 'が枯れる', 'N1', '', 'héo úa ( không có khả năng hồi phục)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が廃れる', 'が廃れる', 'N1', '', '① lỗi mốt, lỗi thời, không còn được xem trọng nữa (流行が廃れる sự lưu hành bị quên lãng, 年長者を敬う価値観は廃れるのだろうか）trở nên phế② trở nên suy yếu　（林業が廃れてしまった  lâm nghiệp đã trở nên suy kém, trở nên phế)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('(が)よみがえる', '(が)よみがえる', 'N1', '', 'được làm sống lại (記憶、結婚式のときの感動が、）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が復活する', 'が復活する', 'N1', '', 'được sống lại', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が生き返す', 'が生き返す', 'N1', '', 'sống lại', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('をもたらす', 'をもたらす', 'N1', '', '① mang đến (宝石は、身につけると幸運をもたらすと言われている、）② mang lại (cả nghĩa điều tốt và xấu) (インターネットは情報の革命をもたらした）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が潤る', 'が潤る', 'N1', '', '① ẩm ướt (雨で畑が潤った、クリームを塗ると肌が潤った）② trái tim dạt dào, xúc động (自然の中にいると、心が潤ってくる）③ dồi dào, trở nên phong phú (財政が潤る tài chính dồi dào)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('を潤す', 'を潤す', 'N1', '', '① làm ướt (水を飲んでのどを潤す、川が畑を潤す）② làm cho dạt dào tình cảm (芸術は人の心を潤す）③ làm cho dạt dào （財政を潤す làm cho tài chính phong phú, nhiều lên)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('が和らぐ', 'が和らぐ', 'N1', '', '① trở nên dịu bớt, ít gay gắt (寒さ、衝撃、痛み、怒りが和らぐ）② làm cho tình hình dịu, bớt căng thẳng (気持ち、表情、雰囲気が和らぐ）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('（が）とろける', '（が）とろける', 'N1', '', '① tan chảy (チーズがとろける）② trở nên tan chảy, dịu nhẹ lại (心がとろける trong lòng cảm thấy dịu lại)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('をとろかす', 'をとろかす', 'N1', '', 'làm tan chảy (あめをとろかす làm tan kẹo, 心をとろかす làm cho những trạng thái không tốt giảm đi)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('（が）くつろぐ', '（が）くつろぐ', 'N1', '', 'thư giản, relax (家でゆっくりくつろぐ）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('一気に', 'いっきに', 'N1', 'in one go; in one gulp; in one breath; without stopping; without pausing; without a rest; in one sitting; at a stretch', 'làm 1 lần không nghỉ (階段を一気に駆け上がる、ビールを一気に飲み干す）', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('きっぱり（と）', 'きっぱり（と）', 'N1', '', 'thẳng thừng, dứt khoát (きっぱりと断る、きっぱりした態度）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('てきぱき（と）', 'てきぱき（と）', 'N1', '', 'tháo vát, nhanh nhẹn (てきぱきと家事をこなす、てきぱき働く、片付く）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('きびきび', 'キビキビ', 'N1', 'briskly; energetically; livelily; efficiently; crisply; vigorously', 'nhanh nhẹn, hăng hái', 'adv, adv-to, vs') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('だらだら（と）する', 'だらだら（と）する', 'N1', '', '① lề mề, trạng thái không muốn làm (休みはだらだら過ごした、会議はだらだらと５時間も続いた）② dốc thoai thoải (だらだらと続く坂道、山道をだらだらと下る）③ chậm chậm, từ từ (傷口から血がだらだらと流れた）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ぐずぐず（と）する', 'ぐずぐず（と）する', 'N1', '', '① lề mề, ngập ngừng không làm (布団の中でぐずぐずしていて、起きられない、返事をぐずぐず引き延ばす② càu nhàu (ぐずぐず言わずに đừng có càu nhàu)③ sụt sịt mũi khi bị cảm (鼻がぐずぐずする）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ゆうゆう（と）', 'ゆうゆう（と）', 'N1', '', '① ung dung, thong dong (鳥がゆうゆうと空を飛ぶ、悠々と歩く、悠々たる態度 thái độ thong dong )② dư dả khả năng hoàn thành diều gì đó (悠々間に合う、悠々合格する）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('いそいそ（と）', 'いそいそ（と）', 'N1', '', 'háo hức (デートらしく、いそいそと出かけて行く）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('とっさに', 'とっさに', 'N1', 'at once; immediately; instantly; in an instant; quickly; suddenly; on the spur of the moment', 'đột nhiên, bất ngờ　（どっさのこと sự việc bất ngờ)', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('じっくり（と）', 'じっくり（と）', 'N1', '', 'từ từ cẩn thận thực hiện (じっくりと考える suy nghĩ từ từ cẩn thận, 骨付き肉をじっくりと煮込む)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('おろおろ（と）する', 'おろおろ（と）する', 'N1', '', 'cuống cuồng (おろおろするばかりで、何もできなかった/心配で、おろおろ歩き回る)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('まごまごする', 'まごまごする', 'N1', '', 'lúng túng, bối rối, chậm trễ  (操作方法が分からず、まごまごしている, まごまごしていると置いていくぞ）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ぶつぶつ（と）', 'ぶつぶつ（と）', 'N1', '', '① làu bàu (ぶつぶつとつぶやく  làu bàu, phàn nàn)② phàn nàn (ぶつぶつ言う)③ nổi mụn (顔にぶつぶつができた）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('うっとり（と）する', 'うっとり（と）する', 'N1', '', 'chìm đắm, mải mê vào (うっとりと音楽に聞き入っていた、うっとりした表情を浮かべた)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ゆったり（と）する', 'ゆったり（と）する', 'N1', '', '① thong thả, thong dong ② rộng rãi (ゆったりした服）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('しみじみ（と）', 'しみじみ（と）', 'N1', '', '① đầy đủ, hoàn toàn (健康の有難さ感じる）② cảm xúc lắng đọng (しみじみに語り合う、しみじみ（と）した気分になった）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('つくづく（と）', 'つくづく（と）', 'N1', '', '① thật sự để ý đến điều gì đó (鏡でつくづくと自分の顔を眺める、自分の将来をつくづくと考える）② thật lòng (つくづく自分が嫌になる）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('よくよく', 'よくよく', 'N1', 'the ... after next; two ... later; two ... after', 'để ý, chú tâm', 'adj-pn') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('がっくり（と）する', 'がっくり（と）する', 'N1', '', '① suy sụp tinh thần② giảm sút (売り上げはがっくり落ちた）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('うんざりする', 'うんざりする', 'N1', '', 'chán ngấy, ngán ngẩm　（いくら好きな料理でも、毎日食べるとうんざりする）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('てっきり', 'てっきり', 'N1', 'surely; certainly; without doubt', 'tưởng là…(てっきり場所を間違えたのだと思ったが、実際はみんなが遅刻したのだった）', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('いっそ', 'いっそ', 'N1', 'rather; sooner; preferably; might as well; just', 'nếu, so với vế 1 thì THÀ làm vế 2 còn hơnこんなにつらい思いをするくらいなら、いっそしんでしまいたい', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('きっかり（と）', 'きっかり（と）', 'N1', '', '① vừa đúng (９時きっかり、きっかり３０００円）② đúng đắn, chính xác (きっかりと分ける chia đúng, chia đều)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('きっちり（と）', 'きっちり（と）', 'N1', '', '① thực hiện đúng, chỉnh chu công việc (調味料をきっちり測る、きっちりと計画を立てる）② vừa đúng (きっちり１メートル、きっちり百万円)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('誠に', 'まことに', 'N1', 'really; truly; very; extremely; exceedingly; sincerely', 'thật sự rất … (まことにありがとうございます、まことに申し訳ありません）', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ことに', 'ことに', 'N1', 'especially; particularly; unusually; above all', 'đặc biệt là …(今晩はことに冷える）', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('まさに', 'まさに', 'N1', 'exactly; just; precisely; really; truly; surely; certainly; without doubt', '① chắc chắn là (この絵はまさに彼に最高傑作だ)② ngay lúc này (今まさに、新しい年が明けようとしている）', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ひたすら', 'ひたすら', 'N1', 'intently; single-mindedly; devotedly; solely; earnestly; with all one''s heart', 'chẳng thể làm gì ngoài việc …(ひたすら待ち続けた chẳng thể làm gì ngoài việc tiếp tục chờ đợi)', 'adv, adj-na') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('一途に', 'いちずに', 'N1', 'wholeheartedly; single-mindedly; earnestly; intently; determinedly', 'toàn tâm toàn ý', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('一心に', 'いっしんに', 'N1', 'wholeheartedly; single-mindedly; fervently; intently', 'tập trung', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('あくまで（も）', 'あくまで（も）', 'N1', '', '① kiên quyết đến cùng (あくまでも戦うつもり)② dù gì thì cũng chỉ…mà thôi (決定権はあくまでも社長になる ）③ rất (空はあくまでも青くて、澄み切っていた）', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('めっきり', 'めっきり', 'N1', 'remarkably; noticeably; visibly; considerably; perceptibly; appreciably; very much', 'rõ ràng, cảm nhận một cách rõ rệt (めっきり涼しくなった、めっきり体が弱くなった）', 'adv, adv-to') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('かろうじて', 'かろうじて', 'N1', 'barely; narrowly; only just; with difficulty', 'đạt được kết quả như ý muốn một cách suýt soát (かろうじて予選をパスした、かろうじて難を逃れた）', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('あえて', 'あえて', 'N1', 'purposely (of something needless, unexpected or seemingly counterproductive, etc.); daringly (doing something); deliberately; intentionally', '① mạnh dạn, mạo muội (あえて反対意見を述べてみた）② không cần thiết phải… (あえて断るまでもないと思う）', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('あわや', 'あわや', 'N1', 'nearly; almost; on the verge (of happening)', 'chỉ một xíu nữa là…(あわや衝突かというところで、あわや予選敗退かと心配した )', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('もろに', 'もろに', 'N1', 'completely; all the way; altogether; bodily', 'trực tiếp, chính diện, hoàn toàn (ボールがもろに顔に当たった）', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('いやに', 'いやに', 'N1', 'awfully; terribly', 'rất, cực kì, khác hoàn toàn với bình thường (いやにおとなしい、いやに蒸し暑い）', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('妙に', '妙に', 'N1', '', 'khác thường', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('やけに', 'やけに', 'N1', 'awfully; frightfully; desperately; violently; unduly; extremely', '① cực kì kinh khủng (今日はやけに暑い）② khác bình thường (彼女は今日、やけに優しい）', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('むやみに', 'むやみに', 'N1', 'thoughtlessly; recklessly; rashly; indiscriminately; indiscreetly; at random', '① khinh suất (むやみに人を信じる）② quá mức　（むやみに忙しい）', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('やたらに', 'やたらに', 'N1', '', '① quá mức, quá đáng　（やたらにのどが渇く）② bừa bãi; ngẫu nhiên③ Không thận trọng; khinh suất', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('むやみやたらに', 'むやみやたらに', 'N1', '', 'cực kì', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('めったやたらに', 'めったやたらに', 'N1', '', 'cực kì', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('何しろ', 'なにしろ', 'N1', 'in any case; at any rate; anyhow; anyway; as you know; for you see; particularly', 'dù có các sự tình khác nhưng muốn nhấn mạnh vào điều này, điểm này (暖房がないので、何しろ寒くて）', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('専ら', 'もっぱら', 'N1', 'wholly; solely; entirely; exclusively; devotedly; fixedly', 'Chủ yếu, hầu hết (休みの日はもっぱら山歩きをしている、もっぱらのうわさ )', 'adv, adj-no') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('専らのうわさ', '専らのうわさ', 'N1', '', 'hầu hết là tin đồn thôi', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('一応', 'いちおう', 'N1', 'more or less; though not quite satisfactorily; after a fashion; pretty much; roughly; so far as it goes; technically', '① tạm thời, tạm (一応頼んでみた）② ít nhiều, không phải 100% nhưng cũng 90% (一応の仕事の流れは分かった）', 'n, adj-no, adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('一旦', 'いったん', 'N1', 'once', '① làm cái gì đó 1 chút xíu rồi quay lại việc chính (自転車から一旦降りて、）② một lần (一旦引き受けておいて後で断るんなんて、無責任だ）', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('一旦停止', '一旦停止', 'N1', '', 'tạm dừng một chút', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ひとまず', 'ひとまず', 'N1', 'for now; for the time being; for the present', 'tạm thời (父の手術が無事に終わり、ひとまず安心だ）', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('追って', 'おって', 'N1', 'later on; shortly; presently; afterwards; in due course; by and by', 'sau, sẽ làm việc đó sau (追って連絡する sẽ liên lạc lại sau, 追ってお知らせする sẽ thông báo sau)', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('現に', 'げんに', 'N1', 'actually; really', 'thực sự là (現に、今日もつまらないミスをしている)', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('言わば', 'いわば', 'N1', 'so to speak; so to call it; as it were', 'có thể nói là (成田空港は言わば日本の玄関だ）', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('いかに', 'いかに', 'N1', 'how; in what way', '① như thế nào (人生、いかに生きるべきか)② đến mức độ nào (彼がいかに頑張ったか、私はよく知っている）③ dẫu cho thế nào đi nữa (いかに苦しても,…　dẫu có đau đớn thế nào đi chăng nữa thì…)', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('いかなる', 'いかなる', 'N1', 'what kind of; what sort of; what', 'dù trong bất kì…(いかなる場合においても cho dù đặt vào bất kì trường hợp nào)', 'adj-pn') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('一律に', 'いちりつに', 'N1', 'uniformly; evenly; equally; indiscriminately; across the board', 'đồng đều ( ボーナスとして一律に一万円支給された、各社一律の値上げ）', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('一様に', '一様に', 'N1', '', 'đồng đều', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('各々', 'おのおの', 'N1', 'each', 'mỗi người (おのおの役割がある、おのおの準備してください）', 'n, adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('もはや', 'もはや', 'N1', 'already; now', 'đã = すでに (もはや手遅れだった）', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ともすれば', 'ともすれば', 'N1', 'apt to (do); liable to; prone to', 'có khuynh hướng, có xu hướng (ともすれば楽な方へ流れがちだ）', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ともすると', 'ともすると', 'N1', 'apt to (do); liable to; prone to', 'có khuynh hướng, có xu hướng (ともすれば楽な方へ流れがちだ）', 'exp, adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ややもすると', 'ややもすると', 'N1', 'being apt to; being liable to; being inclined to', 'có xu hướng', 'exp, adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('依然（として）', '依然（として）', 'N1', '', 'vẫn, vẫn như thế (台風は依然強い勢力を保ったまま、犯人は依然捕まっていない) =まだ、今だに', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('漠然と', '漠然と', 'N1', '', 'ngờ ngợ, không rõ ràng ( 漠然とした不安を抱いている có cảm giác gì đó bất an)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('漠然たる不安', '漠然たる不安', 'N1', '', 'có cảm giác gì đó bất an', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('まして', 'まして', 'N1', 'still more; to say nothing of; not to mention', 'nói chi đến, huống chi (　若い人でも大変なのだから、まして老人には無理だろう）', 'exp, adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('「名詞」にもまして', '「名詞」にもまして', 'N1', '', 'còn hơn cả N (暑さにもまして耐えがたいのは、湿度の高さだ　cái mà khó chịu hơn cái nóng là độ ẩm cao)', '') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ましてや', 'ましてや', 'N1', 'much less; to say nothing of', 'huống chi', 'exp, adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ひいては', 'ひいては', 'N1', 'by extension; in turn; by the same token; in addition; as well; consequently', 'nói rộng ra thì… (アメリカの不況は日本に、ひいては我が家の家計にも大きな影響を及ぼす）', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('おのずから', 'おのずから', 'N1', 'naturally; in due course; by itself; of its own accord', 'một cách tự nhiên sự việc sẽ xảy ra (　よく読めばおのずからわかるだろう đọc kĩ thì tự nhiên sẽ hiểu )', 'adv') ON CONFLICT DO NOTHING;
INSERT INTO vocabulary (word_ja, reading, jlpt_level, meaning_en, meaning_vi, part_of_speech) VALUES ('ひとりでに', 'ひとりでに', 'N1', 'by itself; automatically; naturally', 'tự nhiên =　自然に', 'adv') ON CONFLICT DO NOTHING;
